'use strict';
// REF GEAR — the reference hero's outfit on the ref rig (models/ref.js), every item a separate piece over the casual base:
// lavender plate armour (breastplate, pauldrons, bracers, belt, knee guards), brown boots, red scarf + cape, round red
// shield (left arm), short sword (right hand). Exact reference colours; the sword blade is a 1 px line (white, like the reference), and the
// sword's smear (attack frames 1-3) is generated by forge.js from the hand -> tip path, one flat tone, no outline.
const NAVY = '#1f2357';
const { SCALE } = require('./ref.js');
// every length below is in reference pixels; geo() scales a prim / socket to the rig's SCALE (32 px body)
const sc = v => Array.isArray(v) ? v.map(x => x * SCALE) : v * SCALE;
const geo = p => { const o = Object.assign({}, p); for (const k of ['c', 'r', 'a', 'b', 'h', 'at']) if (o[k]) o[k] = sc(o[k]);
  for (const k of ['ra', 'rb']) if (o[k] != null) o[k] = sc(o[k]);
  if (o.clip) o.clip = (Array.isArray(o.clip[0]) ? o.clip : [o.clip]).map(c => [c[0], c[1], c[2], c[3] * SCALE]); return o; };
const layer = L => Object.assign({}, L, { prims: L.prims.map(geo) });
const RED = { ramp: ['#670948', '#a62144', '#a62144', '#a62144'], tones: [0.9, 0.5, -0.35] };
const notAttack = fn => (a, f) => a.startsWith('attack') ? {} : fn(a, f);

const SIDES = [['R', -1], ['L', 1]];
const PARTS = require('./ref-parts.js');
const PLATE_KEY = { d: ['plate', 0], a: ['plate', 1], A: ['plate', 2], L: ['plate', 3], N: ['strap', 0] };
const armour = {
  id: 'armour', slot: 'chest',
  layers: [Object.assign(layer({ id: 'armour', bias: 0.7, mats: {
    plate: { ramp: ['#433a60', '#644f77', '#907ca1', '#b5a0ba'], tones: [0.9, 0.2, -0.3] },
    strap: { ramp: [NAVY, NAVY, NAVY, NAVY] },
    sleeve: { ramp: [NAVY, '#104097', '#104097', '#104097'], tones: [0.95, 0.5, -0.2] },   // padded sleeve under the pauldron
  }, prims: [   // the volumes give the silhouette and the depth; the sprites below draw the plate's face over them
    { bone: 'chest', mat: 'plate', part: 'torso', shape: 'ell', c: [0, 2.4, 0.2], r: [4.3, 3.3, 3.8] },
    { bone: 'spine', mat: 'strap', part: 'torso', shape: 'box', c: [0, 0.9, 0], h: [3.4, 0.75, 2.4], round: 0.5 },
    ...SIDES.flatMap(([sd, k]) => [
      { bone: 'upper' + sd, mat: 'plate', part: 'pauldron' + sd, shape: 'ell', c: [0.3 * k, -0.2, 0], r: [1.9, 2.0, 2.15] },
      { bone: 'upper' + sd, mat: 'sleeve', part: 'arm' + sd, shape: 'cap', a: [0, -0.5, 0], b: [0, -3.1, 0], ra: 1.25, rb: 1.2 },
      { bone: 'fore' + sd, mat: 'plate', part: 'arm' + sd, shape: 'cap', a: [0, 0, 0], b: [0, -2.0, 0], ra: 1.25, rb: 1.15 },
      { bone: 'shin' + sd, mat: 'strap', part: 'knee' + sd, shape: 'cap', a: [0, -0.3, 0], b: [0.3 * k, -1.4, 0], ra: 1.4, rb: 1.35 },
    ]),
  ] }), {
    // the breastplate + belt and the pauldrons: hand-authored pixel parts per facing (models/ref-parts.js)
    sprites: [
      { bone: 'chest', at: sc([0, 2.4, 4.2]), part: 'torso', key: PLATE_KEY, dirs: PARTS.PLATE },
      ...SIDES.map(([sd, k]) => ({ bone: 'upper' + sd, at: sc([0.3 * k, -0.2, 2.4]), part: 'pauldron' + sd, key: PLATE_KEY, dirs: PARTS.PAULDRON })),
    ] })],
};
const boots = {
  id: 'boots', slot: 'boots',
  layers: [layer({ id: 'boots', bias: 0.3, mats: { leather: { ramp: ['#592104', '#592104', '#a64e21', '#a64e21'], tones: [0.95, 0.15, -0.5] } },
    prims: SIDES.flatMap(([sd, k]) => [
      { bone: 'shin' + sd, mat: 'leather', part: 'boot' + sd, shape: 'cap', a: [0.3 * k, -1.6, 0], b: [0.6 * k, -4.6, 0], ra: 1.35, rb: 1.3 },
      { bone: 'foot' + sd, mat: 'leather', part: 'boot' + sd, shape: 'ell', c: [0, -0.3, 0.4], r: [1.35, 1.35, 1.75], clip: [0, -1, 0, 1.2] },
    ]) })],
};

// the cape: hand-authored pixel parts per facing (models/ref-parts.js CAPE: fixed 12 px length) hung from the cape bone,
// the scarf stays a volume. Secondary motion on a lagged 3-segment spring (forge.js springOf): the walk drives it forward
// with a side kick on each step (frames 1, 4: the sway alternates), the attack swings it against the sword tip.
const CAPE = { segs: 3, stiff: 0.45, damp: 0.45, warm: 3, min: { idle: 0.5, other: 1 },
  drive: { walk: { fwd: [4, 4, 4, 4, 4, 4], side: [0, 2.5, 0, 0, -2.5, 0] } },
  counter: { anims: ['attack'], bone: 'weapon', at: sc([0, 8.6, 0]), gain: 0.15 } };
const cape = {
  id: 'cape', slot: 'back',
  // two layers, so the cape's own layer holds the drawing alone (its pixel area is the drawing's, the scarf stacks on it)
  layers: [layer({ id: 'scarf', group: 'cape', mats: { cloth: RED }, prims: [
    { bone: 'chest', mat: 'cloth', part: 'scarf', shape: 'ell', c: [0, 4.3, 0.2], r: [4.65, 2.15, 4.75] },
    { bone: 'chest', mat: 'cloth', part: 'scarf', shape: 'ell', c: [0, 3.0, 4.4], r: [2.2, 1.8, 1.0] },
  ] }), { id: 'cape', group: 'cape', mats: { cloth: RED }, prims: [],
    sprites: [{ bone: 'cape', face: 'chest', part: 'cape', key: { r: ['cloth', 1], R: ['cloth', 0], N: NAVY }, dirs: PARTS.CAPE, spring: CAPE }] }],
};

const SHIELD = { rest: { aim: [-0.19, 1, 0], roll: [0.55, 0, 0.83] }, walk: { aim: [-0.07, 1, 0.05], roll: [0.6, 0, 0.8] } };
const shield = {
  id: 'shield', slot: 'offhand',
  layers: [Object.assign(layer({ id: 'shield', mats: {
    face: RED, back: { ramp: ['#592104', '#592104', '#a64e21', '#a64e21'], tones: [0.95, 0.3, -2] },
    rim: { ramp: ['#a64e21', '#a64e21', '#cc7c52', '#e5e0ac'], tones: [0.55, 0.0, -0.6] },
    boss: { ramp: ['#cc7c52', '#cc7c52', '#e5e0ac', '#e5e0ac'], tones: [0.9, 0.2, -2] },
  }, prims: [
    { bone: 'offhand', mat: 'back', part: 'shield', shape: 'ell', c: [0, 0.2, 0.35], r: [3.4, 3.4, 0.45] },
    { bone: 'offhand', mat: 'rim', part: 'shield', shape: 'ell', c: [0, 0.2, 0.75], r: [3.7, 3.7, 0.4] },
    { bone: 'offhand', mat: 'face', part: 'shield', shape: 'ell', c: [0, 0.1, 1.05], r: [3.0, 3.0, 0.5] },
    { bone: 'offhand', mat: 'boss', part: 'shield', shape: 'ell', c: [0, 0.1, 1.55], r: [0.8, 0.8, 0.45] },
  ] }), {
    // the face (rim, boss) or the wooden back as pixel parts over the volumes, by the way the face points
    sprites: [
      { bone: 'offhand', at: sc([0, 0.1, 2.1]), part: 'shield', key: { y: ['rim', 3], t: ['rim', 2], r: ['face', 1], R: ['face', 0], Y: ['boss', 2] }, dirs: PARTS.SHIELD_FACE },
      { bone: 'offhand', at: sc([0, 0.2, -0.3]), part: 'shield', key: { B: ['back', 0], s: ['back', 2] }, dirs: PARTS.SHIELD_BACK },
    ] })],
  pose: a => ({ offhand: a === 'walk' ? SHIELD.walk : SHIELD.rest }),
};

const SWORD = { rest: [-0.3, 0.85, 0.42], walk: [0, 0.85, 0.7] };   // held low in front on the run
const sword = {
  id: 'sword', slot: 'weapon', class: 'sword', smear: '#fafaf6',
  layers: [layer({ id: 'sword', mats: { blade: { ramp: ['#fafaf6', '#fafaf6', '#fafaf6', '#fafaf6'], flat: 0 }, hilt: { ramp: ['#a64e21', '#a64e21', '#ba8a38', '#ba8a38'], tones: [0.9, 0.2, -2] } },
    prims: [
      { bone: 'weapon', mat: 'hilt', part: 'hilt', shape: 'cap', a: [0, -0.9, 0], b: [0, 1.0, 0], ra: 0.6, rb: 0.6 },
      { bone: 'weapon', mat: 'blade', part: 'blade', shape: 'line', a: [0, 1.2, 0], b: [0, 8.6, 0], conn4: true },
    ] })],
  sockets: { tip: geo({ bone: 'weapon', at: [0, 8.6, 0] }) },
  pose: notAttack(a => ({ weapon: { aim: a === 'walk' ? SWORD.walk : SWORD.rest } })),
};

const pieces = { armour, boots, cape, shield, sword };
const loadouts = { base: [], hero: ['armour', 'boots', 'cape', 'shield', 'sword'] };
module.exports = { pieces, loadouts, NAVY, CAPE, SWORD, SHIELD };
